/* Sanitiser for SVG that did not come from us.
 *
 * Panel artwork is generated by a model from a scene the user pasted, so the
 * markup is attacker-influenced twice over: whoever wrote the scene text can
 * try to steer the model, and a self-hosted/local model can return anything at
 * all. That artwork has to end up as live DOM to be visible and editable, so
 * escaping it (the rule everywhere else in this app) is not an option here —
 * escaped SVG renders as text, not a drawing.
 *
 * So instead: parse, walk, and keep only a fixed allow-list of shape elements
 * and presentation attributes. Anything unrecognised is dropped rather than
 * repaired. SVG has a large attack surface — <script>, on* handlers,
 * <foreignObject> (arbitrary HTML), <animate> (can retarget an href),
 * <image>/<a>/<use> (external or javascript: references), and url() in a
 * paint or style value — and every one of those is refused outright below.
 *
 * Two hard rules keep this honest:
 *   1. Sanitise to DOM nodes, never to a string that gets re-parsed. A
 *      sanitise-then-innerHTML round trip reopens mutation-XSS, where markup
 *      that parsed as inert in one context parses as live in another.
 *   2. Sanitise on the way IN and again on the way OUT of storage. localStorage
 *      is writable by anything else running on the origin, so stored artwork is
 *      treated as untrusted on load exactly like a fresh model response.
 */

const SVG_NS = 'http://www.w3.org/2000/svg';

/* Deliberately omits: script, foreignObject, image, a, use, animate, set,
   animateTransform, animateMotion, style, filter and every filter primitive,
   switch, marker, pattern, symbol, metadata. None are needed to draw a
   storyboard panel, and each one is either directly executable or a known
   route to an external fetch. */
const ALLOWED_TAGS = new Set([
  'g',
  'path',
  'line',
  'polyline',
  'polygon',
  'rect',
  'circle',
  'ellipse',
  'text',
  'tspan',
  'defs',
  'linearGradient',
  'radialGradient',
  'stop',
  'clipPath',
  'title',
  'desc',
]);

const GLOBAL_ATTRS = new Set([
  'id',
  'class',
  'transform',
  'opacity',
  'fill',
  'fill-opacity',
  'fill-rule',
  'stroke',
  'stroke-width',
  'stroke-opacity',
  'stroke-linecap',
  'stroke-linejoin',
  'stroke-miterlimit',
  'stroke-dasharray',
  'stroke-dashoffset',
  'clip-path',
  'clip-rule',
  'paint-order',
  'vector-effect',
]);

const TEXT_ATTRS = [
  'x',
  'y',
  'dx',
  'dy',
  'font-family',
  'font-size',
  'font-weight',
  'font-style',
  'letter-spacing',
  'word-spacing',
  'text-anchor',
  'dominant-baseline',
  'xml:space',
];

const TAG_ATTRS = {
  path: ['d', 'pathLength'],
  line: ['x1', 'y1', 'x2', 'y2'],
  polyline: ['points'],
  polygon: ['points'],
  rect: ['x', 'y', 'width', 'height', 'rx', 'ry'],
  circle: ['cx', 'cy', 'r'],
  ellipse: ['cx', 'cy', 'rx', 'ry'],
  text: TEXT_ATTRS,
  tspan: TEXT_ATTRS,
  linearGradient: ['x1', 'y1', 'x2', 'y2', 'gradientUnits', 'gradientTransform', 'spreadMethod'],
  radialGradient: [
    'cx',
    'cy',
    'r',
    'fx',
    'fy',
    'gradientUnits',
    'gradientTransform',
    'spreadMethod',
  ],
  stop: ['offset', 'stop-color', 'stop-opacity'],
  clipPath: ['clipPathUnits'],
};

/* Budgets. A model that loops, or a hand-edited localStorage entry, should
   degrade to "some of the drawing is missing" rather than locking up the tab. */
const MAX_INPUT_CHARS = 400000;
const MAX_NODES = 4000;
const MAX_DEPTH = 24;
const MAX_TEXT_CHARS = 500;
const MAX_ATTR_CHARS = 8000;

const NAMED_COLORS = new Set([
  'none',
  'transparent',
  'currentcolor',
  'black',
  'white',
  'red',
  'green',
  'blue',
  'yellow',
  'orange',
  'purple',
  'grey',
  'gray',
  'brown',
  'pink',
  'cyan',
  'magenta',
  'silver',
  'gold',
  'navy',
  'teal',
  'olive',
  'maroon',
  'lime',
  'aqua',
  'fuchsia',
  'beige',
  'ivory',
  'tan',
  'khaki',
  'crimson',
  'indigo',
  'violet',
  'salmon',
  'coral',
  'darkgrey',
  'darkgray',
  'lightgrey',
  'lightgray',
  'dimgrey',
  'dimgray',
  'slategrey',
  'slategray',
]);

const HEX_RE = /^#(?:[0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i;
const FUNC_COLOR_RE = /^(?:rgb|rgba|hsl|hsla)\(\s*[0-9a-z.,%\s/-]+\)$/i;
/* Only a same-document fragment reference. url(http://…), url(data:…) and
   url(javascript:…) all fail this, which is the entire point. */
const LOCAL_REF_RE = /^url\(\s*['"]?#[A-Za-z][\w:.-]*['"]?\s*\)$/;
const NUMERIC_RE = /^[-+0-9.eE\s,%]+$/;
const TRANSFORM_RE = /^[a-zA-Z0-9\s,.()%+-]*$/;
const PATH_DATA_RE = /^[-+0-9.eE\s,mMzZlLhHvVcCsSqQtTaA]*$/;
const FONT_FAMILY_RE = /^[\w\s,'"-]+$/;
const IDENT_RE = /^[A-Za-z][\w:.-]*$/;

function isSafePaint(value) {
  const v = value.trim();
  if (!v) return false;
  if (NAMED_COLORS.has(v.toLowerCase())) return true;
  if (HEX_RE.test(v)) return true;
  if (FUNC_COLOR_RE.test(v)) return true;
  if (LOCAL_REF_RE.test(v)) return true;
  return false;
}

/* Per-attribute value rules. Anything not listed falls through to the
   conservative default of "must look numeric", so a new attribute added to the
   allow-lists above can't accidentally smuggle in a URL. */
function isSafeAttrValue(name, value) {
  if (value.length > MAX_ATTR_CHARS) return false;
  const lower = value.toLowerCase();
  // Belt and braces: no scheme-ish text survives anywhere, whatever the rule below says.
  if (lower.includes('javascript:') || lower.includes('data:') || lower.includes('&#'))
    return false;

  switch (name) {
    case 'fill':
    case 'stroke':
    case 'stop-color':
      return isSafePaint(value);
    case 'clip-path':
      return value.trim() === 'none' || LOCAL_REF_RE.test(value.trim());
    case 'd':
      return PATH_DATA_RE.test(value);
    case 'transform':
    case 'gradientTransform':
      return TRANSFORM_RE.test(value) && !lower.includes('url(');
    case 'id':
    case 'class':
      return IDENT_RE.test(value.trim());
    case 'font-family':
      return FONT_FAMILY_RE.test(value);
    case 'font-weight':
    case 'font-style':
    case 'text-anchor':
    case 'dominant-baseline':
    case 'stroke-linecap':
    case 'stroke-linejoin':
    case 'fill-rule':
    case 'clip-rule':
    case 'paint-order':
    case 'vector-effect':
    case 'spreadMethod':
    case 'gradientUnits':
    case 'clipPathUnits':
    case 'xml:space':
      return /^[a-zA-Z- ]+$/.test(value);
    default:
      return NUMERIC_RE.test(value);
  }
}

function allowedAttrsFor(tag) {
  const extra = TAG_ATTRS[tag] || [];
  return (name) => GLOBAL_ATTRS.has(name) || extra.includes(name);
}

/* Reads the root <svg> out of whatever the model actually sent — usually a
   full document, sometimes a bare fragment, often wrapped in prose or a code
   fence. Returns a parsed root element, or null if nothing usable is there. */
function parseToRoot(raw) {
  let text = String(raw || '').slice(0, MAX_INPUT_CHARS);
  text = text.replace(/```(?:svg|xml|html)?/gi, '').trim();

  const start = text.indexOf('<svg');
  const end = text.lastIndexOf('</svg>');
  if (start !== -1 && end !== -1 && end > start) {
    text = text.slice(start, end + 6);
  } else if (start === -1) {
    // A bare fragment of shapes with no root — give it one so it parses.
    text = `<svg xmlns="${SVG_NS}">${text}</svg>`;
  } else {
    return null;
  }

  let doc;
  try {
    doc = new DOMParser().parseFromString(text, 'image/svg+xml');
  } catch {
    return null;
  }
  if (!doc || !doc.documentElement) return null;
  if (doc.getElementsByTagName('parsererror').length > 0) return null;
  if (doc.documentElement.localName !== 'svg') return null;
  return doc.documentElement;
}

/* Rebuilds the tree into fresh nodes rather than stripping the parsed ones in
   place. Nothing from the source document survives except element names,
   approved attribute names, and values that passed the checks above — there is
   no path by which an unexamined node reaches the output. */
function cleanInto(source, target, ownerDoc, budget, depth) {
  for (const node of Array.from(source.childNodes)) {
    if (budget.nodes >= MAX_NODES) return;

    if (node.nodeType === 3) {
      const text = node.nodeValue.slice(0, MAX_TEXT_CHARS);
      if (text.trim()) {
        budget.nodes += 1;
        target.appendChild(ownerDoc.createTextNode(text));
      }
      continue;
    }
    // Elements only: comments, CDATA and processing instructions are dropped.
    if (node.nodeType !== 1) continue;

    const tag = node.localName;
    if (!ALLOWED_TAGS.has(tag)) continue;
    if (depth >= MAX_DEPTH) continue;

    budget.nodes += 1;
    const clean = ownerDoc.createElementNS(SVG_NS, tag);
    const isAllowed = allowedAttrsFor(tag);

    for (const attr of Array.from(node.attributes)) {
      // node.name keeps any prefix (xlink:href, on:click); check the whole
      // thing, since the bare localName would hide a namespaced handler.
      const name = attr.name;
      const lower = name.toLowerCase();
      if (lower.startsWith('on')) continue;
      if (lower.includes('href')) continue;
      if (lower === 'style') continue;
      if (lower.startsWith('xmlns')) continue;
      if (!isAllowed(name)) continue;
      if (!isSafeAttrValue(name, attr.value)) continue;
      clean.setAttribute(name, attr.value.trim());
    }

    target.appendChild(clean);
    cleanInto(node, clean, ownerDoc, budget, depth + 1);
  }
}

/* Sanitised artwork as live DOM, ready to append into the stage's <svg>.
   Returns an empty fragment when the input is unusable, so callers can treat
   "hostile" and "empty" the same way. */
export function sanitizeSvgFragment(raw, ownerDoc = document) {
  const fragment = ownerDoc.createDocumentFragment();
  const root = parseToRoot(raw);
  if (!root) return fragment;
  cleanInto(root, fragment, ownerDoc, { nodes: 0 }, 0);
  return fragment;
}

/* Sanitised artwork as a markup string, for persistence and export.
   Serialised FROM the sanitised nodes — never a filtered copy of the input —
   so what gets stored is exactly what was proven safe. */
export function sanitizeSvgMarkup(raw) {
  const fragment = sanitizeSvgFragment(raw);
  const holder = document.createElementNS(SVG_NS, 'svg');
  holder.appendChild(fragment);
  return holder.innerHTML;
}

/* The viewBox the model was asked to draw in, if it supplied a usable one.
   Only ever four finite numbers with a positive extent. */
export function readViewBox(raw) {
  const root = parseToRoot(raw);
  if (!root) return null;
  const attr = (root.getAttribute('viewBox') || '').trim();
  if (!attr) return null;
  const parts = attr.split(/[\s,]+/).map(Number);
  if (parts.length !== 4 || parts.some((n) => !Number.isFinite(n))) return null;
  if (parts[2] <= 0 || parts[3] <= 0) return null;
  return { x: parts[0], y: parts[1], w: parts[2], h: parts[3] };
}

/* Raster layers are not markup, so the allow-list above does not apply to
   them; what is checked instead is where the pixels come from. Two sources
   only: inline image data the app produced itself, or an image the app's
   own server stored (/api/raster/<id>). Anything else — an external URL,
   javascript:, an SVG data URL that could carry script — is refused, so a
   tampered localStorage entry or board file cannot make the page fetch from
   or render someone else's content. */
const RASTER_DATA_RE = /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/;
const RASTER_PATH_RE = /^\/api\/raster\/[A-Za-z0-9_-]{8,80}$/;
const MAX_RASTER_DATA_CHARS = 12 * 1024 * 1024;

export function isSafeRasterSrc(src) {
  if (typeof src !== 'string') return false;
  if (RASTER_PATH_RE.test(src)) return true;
  return src.length <= MAX_RASTER_DATA_CHARS && RASTER_DATA_RE.test(src);
}

/* Replaces an element's children with sanitised artwork. The only supported
   way to put untrusted SVG on screen — assigning to .innerHTML anywhere else
   in the app is a bug. */
export function setSanitizedSvg(el, raw) {
  el.replaceChildren(sanitizeSvgFragment(raw, el.ownerDocument || document));
}
